challenges.solution:
FLAGS = [("FIN", 0x01), ("SYN", 0x02), ("RST", 0x04), ("PSH", 0x08), ("ACK", 0x10), ("URG", 0x20)]


def tcp_flags(value):
    return [name for name, bit in FLAGS if value & bit]

